import type { DifficultyScaling, PersonaDefinition } from "@/lib/domain";
import { PERSONA_ACCENTS } from "@/lib/theme";

function scaling(
  easy: [number, number, string],
  medium: [number, number, string],
  hard: [number, number, string],
  hardClose = 78,
): DifficultyScaling {
  return {
    easy: {
      advanceScore: easy[0],
      escalateBelow: easy[1],
      maxTurns: 6,
      targetObjections: 2,
      intensityCeiling: 1,
      stacksConcerns: false,
      closeScoreRequired: 55,
      coachingNote: easy[2],
    },
    medium: {
      advanceScore: medium[0],
      escalateBelow: medium[1],
      maxTurns: 8,
      targetObjections: 3,
      intensityCeiling: 2,
      stacksConcerns: false,
      closeScoreRequired: 65,
      coachingNote: medium[2],
    },
    hard: {
      advanceScore: hard[0],
      escalateBelow: hard[1],
      maxTurns: 10,
      targetObjections: 4,
      intensityCeiling: 3,
      stacksConcerns: true,
      closeScoreRequired: hardClose,
      coachingNote: hard[2],
    },
  };
}

